import { Link } from "react-router-dom";

function Home() {
  return (
    <div className="container">
      <h1>MediReminder</h1>

      <p>
        Welcome to MediReminder. Manage your medicines and get timely reminders.
      </p>

      <Link to="/login">
        <button>Login</button>
      </Link>

      {" "}

      <Link to="/register">
        <button>Register</button>
      </Link>
    </div>
  );
}

export default Home;
